"""Web-development examples from curated reference tables (CSS, JavaScript, HTML)."""

CSS = [
    ("display: flex", "Makes the element a flex container so its children line up in a row (or column) and can be aligned and spaced easily.",
     ".row { display: flex; gap: 12px; align-items: center; justify-content: space-between; }"),
    ("display: grid", "Makes the element a two-dimensional grid of rows and columns.",
     ".layout { display: grid; grid-template-columns: 240px 1fr; gap: 16px; }"),
    ("position: sticky", "Keeps an element in normal flow until you scroll past a threshold, then it sticks, for example a header.",
     ".header { position: sticky; top: 0; background: #fff; z-index: 10; }"),
    ("box-sizing: border-box", "Makes width and height include padding and border, which makes sizing predictable. Most projects set it globally.",
     "*, *::before, *::after { box-sizing: border-box; }"),
    ("aspect-ratio", "Keeps an element at a fixed width-to-height ratio at any size, with no padding hacks.",
     ".video { width: 100%; aspect-ratio: 16 / 9; }"),
    ("clamp()", "Picks a value between a minimum and a maximum, so text or spacing scales smoothly with the viewport.",
     "h1 { font-size: clamp(1.75rem, 4vw, 3rem); }"),
    ("CSS variables (custom properties)", "Store values once and reuse them. Changing the variable updates everything that uses it, which makes themes easy.",
     ":root { --brand: #6366f1; --radius: 12px; }\n.btn { background: var(--brand); border-radius: var(--radius); }"),
    ("@media (prefers-color-scheme: dark)", "Applies styles only when the visitor's system uses a dark theme.",
     ":root { --bg: #ffffff; --text: #111827; }\n@media (prefers-color-scheme: dark) {\n  :root { --bg: #0b1020; --text: #e5e7eb; }\n}\nbody { background: var(--bg); color: var(--text); }"),
    ("overflow: hidden with text-overflow: ellipsis", "Cuts off long single-line text and shows an ellipsis (...).",
     ".title { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 240px; }"),
    ("object-fit: cover", "Makes an image or video fill its box without being stretched, cropping the extra part.",
     ".avatar { width: 96px; height: 96px; object-fit: cover; border-radius: 50%; }"),
    ("backdrop-filter: blur()", "Blurs whatever is behind a semi-transparent element, giving a frosted-glass look.",
     ".glass { background: rgb(255 255 255 / 0.15); backdrop-filter: blur(12px); border: 1px solid rgb(255 255 255 / 0.25); }"),
    ("transition", "Animates a property change smoothly, for example on hover.",
     ".card { transition: transform 0.2s ease, box-shadow 0.2s ease; }\n.card:hover { transform: translateY(-4px); box-shadow: 0 10px 24px rgb(0 0 0 / 0.15); }"),
    ("@keyframes", "Defines a multi-step animation that you then attach with the `animation` property.",
     "@keyframes fade-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }\n.toast { animation: fade-in 0.3s ease-out both; }"),
    ("scroll-snap-type", "Makes a scrolling container stop neatly on each child, as in carousels.",
     ".carousel { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; }\n.carousel > * { flex: 0 0 80%; scroll-snap-align: start; }"),
    ("gap", "Sets the space between flex or grid children without margin hacks on the first or last item.",
     ".stack { display: flex; flex-direction: column; gap: 1rem; }"),
    ("min-height: 100dvh", "Makes an element at least as tall as the visible screen on phones. `dvh` accounts for the changing browser toolbar, which `vh` does not.",
     ".app { min-height: 100dvh; display: grid; grid-template-rows: auto 1fr auto; }"),
    ("::before and ::after", "Create decorative pseudo-elements without adding extra HTML. They need a `content` property to appear.",
     ".badge::after { content: \"NEW\"; margin-left: 6px; font-size: 0.7em; color: #dc2626; }"),
    (":focus-visible", "Styles the keyboard focus ring without showing it on mouse clicks. Never remove focus indicators without a replacement.",
     "a:focus-visible, button:focus-visible { outline: 3px solid #93c5fd; outline-offset: 2px; }"),
    ("@container queries", "Style a component based on the size of its container instead of the whole viewport, so it adapts wherever it is placed.",
     ".card-wrap { container-type: inline-size; }\n@container (min-width: 400px) {\n  .card { display: grid; grid-template-columns: 120px 1fr; }\n}"),
    ("text-wrap: balance", "Balances the line lengths of short text such as headings, avoiding one lonely word on the last line.",
     "h1, h2 { text-wrap: balance; }"),
]

JS = [
    ("Array.prototype.map", "Creates a new array by transforming every item. The original array is not changed.",
     "const prices = [10, 20, 30];\nconst withTax = prices.map((p) => p * 1.2);\nconsole.log(withTax); // [12, 24, 36]"),
    ("Array.prototype.filter", "Creates a new array with only the items for which the callback returns true.",
     "const nums = [1, 2, 3, 4, 5, 6];\nconst even = nums.filter((n) => n % 2 === 0);\nconsole.log(even); // [2, 4, 6]"),
    ("Array.prototype.reduce", "Folds an array into a single value such as a sum, an object or a count. Always give an initial value.",
     "const cart = [{ price: 5, qty: 2 }, { price: 3, qty: 1 }];\nconst total = cart.reduce((sum, item) => sum + item.price * item.qty, 0);\nconsole.log(total); // 13"),
    ("Array.prototype.find", "Returns the first item that matches, or `undefined` if none does.",
     "const users = [{ id: 1, name: 'Ana' }, { id: 2, name: 'Ben' }];\nconst ben = users.find((u) => u.id === 2);\nconsole.log(ben?.name); // 'Ben'"),
    ("Array.prototype.some and every", "`some` is true if at least one item matches; `every` is true only if all items match.",
     "const ages = [18, 25, 40];\nconsole.log(ages.some((a) => a < 21));  // true\nconsole.log(ages.every((a) => a >= 18)); // true"),
    ("Array.prototype.sort", "Sorts in place. Without a compare function it sorts items as strings, so numbers need a comparator.",
     "const n = [10, 9, 1, 100];\nn.sort();             // [1, 10, 100, 9]  (string order!)\nn.sort((a, b) => a - b); // [1, 9, 10, 100]"),
    ("Object.entries and Object.fromEntries", "Convert an object to [key, value] pairs and back, which makes transforming objects easy.",
     "const prices = { apple: 2, pear: 3 };\nconst doubled = Object.fromEntries(\n  Object.entries(prices).map(([name, p]) => [name, p * 2])\n);\nconsole.log(doubled); // { apple: 4, pear: 6 }"),
    ("Destructuring", "Pulls values out of arrays and objects into variables in one line, with optional defaults and renaming.",
     "const user = { name: 'Mira', address: { city: 'Pune' } };\nconst { name, address: { city }, role = 'guest' } = user;\nconst [first, ...rest] = [1, 2, 3];\nconsole.log(name, city, role, first, rest);"),
    ("Spread syntax", "Copies or merges arrays and objects without changing the originals (a shallow copy).",
     "const a = { x: 1, y: 2 };\nconst b = { ...a, y: 20, z: 3 }; // { x: 1, y: 20, z: 3 }\nconst list = [...[1, 2], 3];      // [1, 2, 3]"),
    ("Optional chaining and nullish coalescing", "`?.` safely reads a property that may not exist, and `??` supplies a default only for null or undefined (not for 0 or an empty string).",
     "const settings = { volume: 0 };\nconsole.log(settings.theme?.color);       // undefined, no error\nconsole.log(settings.volume ?? 50);       // 0\nconsole.log(settings.volume || 50);       // 50 (surprise: 0 is falsy)"),
    ("Template literals", "Backtick strings that embed expressions with `${}` and can span several lines.",
     "const name = 'Ana';\nconst msg = `Hello ${name},\nyou have ${3 + 2} new messages.`;"),
    ("structuredClone", "Makes a deep copy of an object, unlike the spread operator, which copies only the first level.",
     "const original = { a: 1, nested: { b: 2 } };\nconst copy = structuredClone(original);\ncopy.nested.b = 99;\nconsole.log(original.nested.b); // 2"),
    ("Event delegation", "Attach one listener to a parent instead of one per child. It also works for items added later.",
     "document.querySelector('#list').addEventListener('click', (e) => {\n  const item = e.target.closest('li');\n  if (!item) return;\n  console.log('clicked', item.dataset.id);\n});"),
    ("fetch with POST JSON", "Send JSON to a server and check the status before reading the result.",
     "const res = await fetch('/api/items', {\n  method: 'POST',\n  headers: { 'Content-Type': 'application/json' },\n  body: JSON.stringify({ name: 'pen' }),\n});\nif (!res.ok) throw new Error(`HTTP ${res.status}`);\nconst created = await res.json();"),
    ("Set", "A collection of unique values. It is the quickest way to remove duplicates from an array.",
     "const tags = ['a', 'b', 'a', 'c', 'b'];\nconst unique = [...new Set(tags)];\nconsole.log(unique); // ['a', 'b', 'c']"),
    ("Map", "A key-value collection that keeps insertion order and allows any type of key, including objects.",
     "const counts = new Map();\nfor (const w of ['x', 'y', 'x']) counts.set(w, (counts.get(w) ?? 0) + 1);\nconsole.log(counts.get('x')); // 2"),
    ("Closures", "A function remembers the variables from where it was created, even after that outer function has finished.",
     "function makeCounter() {\n  let n = 0;\n  return () => ++n;\n}\nconst next = makeCounter();\nconsole.log(next(), next(), next()); // 1 2 3"),
    ("IntersectionObserver", "Runs code when an element enters or leaves the viewport, ideal for lazy loading and scroll animations.",
     "const io = new IntersectionObserver((entries) => {\n  for (const e of entries) if (e.isIntersecting) e.target.classList.add('visible');\n}, { threshold: 0.2 });\ndocument.querySelectorAll('.reveal').forEach((el) => io.observe(el));"),
    ("requestAnimationFrame", "Runs a callback right before the next screen repaint, the correct way to drive animations from JavaScript.",
     "let x = 0;\nfunction frame() {\n  x += 2;\n  box.style.transform = `translateX(${x}px)`;\n  if (x < 300) requestAnimationFrame(frame);\n}\nrequestAnimationFrame(frame);"),
    ("ES modules", "Split code into files with `export` and `import`. Load the entry file with `type=\"module\"`.",
     "// math.js\nexport const add = (a, b) => a + b;\nexport default function square(n) { return n * n; }\n\n// main.js\nimport square, { add } from './math.js';\nconsole.log(add(2, 3), square(4));"),
]

HTML = [
    ("<button> vs <a>", "Use `<a href>` to navigate to another page or location, and `<button>` for actions on the current page. Both are focusable and keyboard-accessible by default, unlike a clickable `<div>`.",
     "<a href=\"/pricing\">See pricing</a>\n<button type=\"button\" id=\"save\">Save</button>"),
    ("<picture> and srcset", "Serve different image files depending on screen size or format so mobile users download less.",
     "<picture>\n  <source srcset=\"hero.avif\" type=\"image/avif\">\n  <source srcset=\"hero.webp\" type=\"image/webp\">\n  <img src=\"hero.jpg\" alt=\"Mountain at sunrise\" width=\"1200\" height=\"600\" loading=\"lazy\">\n</picture>"),
    ("<details> and <summary>", "A native collapsible section that needs no JavaScript.",
     "<details>\n  <summary>Shipping information</summary>\n  <p>Orders ship within 2 business days.</p>\n</details>"),
    ("<dialog>", "A native modal window with built-in focus handling and an Esc key to close.",
     "<dialog id=\"dlg\"><p>Delete this item?</p><form method=\"dialog\"><button>Cancel</button><button value=\"ok\">Delete</button></form></dialog>\n<button onclick=\"document.getElementById('dlg').showModal()\">Open</button>"),
    ("<form> input types", "Picking the right `type` gives mobile users the right keyboard and gives you free validation.",
     "<input type=\"email\" name=\"email\" autocomplete=\"email\" required>\n<input type=\"tel\" name=\"phone\" inputmode=\"tel\">\n<input type=\"number\" name=\"qty\" min=\"1\" max=\"10\" step=\"1\">\n<input type=\"date\" name=\"day\">"),
    ("meta viewport and charset", "Two tags every page needs: the character encoding and the mobile viewport.",
     "<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"),
    ("semantic page layout", "Using landmark elements instead of many `<div>`s improves accessibility and SEO.",
     "<header>...</header>\n<nav>...</nav>\n<main>\n  <article><h1>Title</h1><p>...</p></article>\n  <aside>Related links</aside>\n</main>\n<footer>...</footer>"),
    ("loading=\"lazy\" and defer", "`loading=\"lazy\"` postpones offscreen images; `defer` loads a script without blocking page rendering and runs it in order after the HTML is parsed.",
     "<img src=\"photo.jpg\" alt=\"Team photo\" width=\"800\" height=\"500\" loading=\"lazy\">\n<script src=\"app.js\" defer></script>"),
]


def generate():
    out = []
    for name, what, code in CSS:
        out.append((f"What does `{name}` do in CSS? Show an example.",
                    f"{what}\n\n```css\n{code}\n```"))
        out.append((f"Explain how to use {name} in CSS.",
                    f"{what}\n\nExample:\n\n```css\n{code}\n```\n\nTip: change one value at a time in your browser's DevTools (Elements tab) to see its effect live."))
    for name, what, code in JS:
        out.append((f"Explain `{name}` in JavaScript with an example.",
                    f"{what}\n\n```javascript\n{code}\n```"))
        out.append((f"How do I use {name} in JavaScript?",
                    f"{what}\n\nExample:\n\n```javascript\n{code}\n```"))
    for name, what, code in HTML:
        out.append((f"How should I use {name} in HTML?",
                    f"{what}\n\n```html\n{code}\n```"))
    return out
